import{_ as e,o as a,c as l,a2 as i}from"./chunks/framework.CFuv5BrO.js";const m=JSON.parse('{"title":"记忆系统","description":"Hearth Memory OS 的五类记忆、记录结构、写入与检索、预算、冲突、遗忘、投毒防护与同步。","frontmatter":{"title":"记忆系统","description":"Hearth Memory OS 的五类记忆、记录结构、写入与检索、预算、冲突、遗忘、投毒防护与同步。","outline":[2,3]},"headers":[],"relativePath":"architecture/memory.md","filePath":"architecture/memory.md","lastUpdated":null}'),r={name:"architecture/memory.md"};function o(d,t,h,s,n,c){return a(),l("div",null,[...t[0]||(t[0]=[i('<p class="eyebrow">MEMORY OS</p><h1 id="记忆系统" tabindex="-1">记忆系统 <a class="header-anchor" href="#记忆系统" aria-label="Permalink to &quot;记忆系统&quot;">​</a></h1><p class="lead">记忆不是聊天记录，而是受约束的判断缓存。它必须有来源、置信度、敏感度、冲突和遗忘策略。</p><h2 id="memory-os" tabindex="-1">Memory OS <a class="header-anchor" href="#memory-os" aria-label="Permalink to &quot;Memory OS&quot;">​</a></h2><p>记忆不是聊天记录，也不是越多越好。它是“受约束的判断缓存”，必须可解释、可纠正、可遗忘。</p><h3 id="五类记忆" tabindex="-1">五类记忆 <a class="header-anchor" href="#五类记忆" aria-label="Permalink to &quot;五类记忆&quot;">​</a></h3><table tabindex="0"><thead><tr><th>类型</th><th>内容</th><th>生命周期</th><th>用途</th></tr></thead><tbody><tr><td>Working Memory</td><td>当前目标、约束、步骤和临时观察</td><td>任务结束清理</td><td>Task Pack、当前计划</td></tr><tr><td>Episodic Memory</td><td>过去任务、结果、失败、人工纠偏</td><td>中期，可摘要</td><td>“上次类似任务怎么做”</td></tr><tr><td>Semantic Memory</td><td>人物、项目、组织、事实、关系</td><td>长期，需来源和有效期</td><td>项目背景、联系人、决策</td></tr><tr><td>User Model</td><td>偏好、沟通风格、边界、习惯、价值排序</td><td>长期，高度可编辑</td><td>减少重复说明</td></tr><tr><td>Procedural Memory</td><td>技能、工作流、工具配方、验证器</td><td>版本化，可回滚</td><td>重复任务复用、Evolution</td></tr></tbody></table><p>Skill 包含权限、版本、评估和回滚元数据；Memory 只保存“曾经有效的经验”。</p><h3 id="记忆记录" tabindex="-1">记忆记录 <a class="header-anchor" href="#记忆记录" aria-label="Permalink to &quot;记忆记录&quot;">​</a></h3><p>每条记忆至少包含：</p><ul><li>id、类型、subject、statement；</li><li>scope（用户、项目、人物、设备）；</li><li>sourceRefs 和 sourceTrust；</li><li>confidence、sensitivity；</li><li>createdAt、lastUsedAt、expiresAt；</li><li>supersedes、conflictsWith；</li><li>status：quarantined / active / superseded / forgotten；</li><li>forgetPolicy。</li></ul><p>关键不是字段多，而是每条记忆都能回答：从哪里来、有多可信、谁能看、何时过期、与哪条冲突、用户如何纠正或删除。</p><h3 id="写入与检索" tabindex="-1">写入与检索 <a class="header-anchor" href="#写入与检索" aria-label="Permalink to &quot;写入与检索&quot;">​</a></h3><p>记忆写入不是“模型说值得记就记”。应先进入候选区，检查来源、敏感度、重复、冲突和用户授权；高敏感内容默认不自动写入。</p><p>检索按任务需要、scope、来源可信度、时效、敏感度和 Token 预算筛选；不能把全部记忆塞入上下文，也不能让不同项目/账户互相污染。</p><h3 id="记忆预算" tabindex="-1">记忆预算 <a class="header-anchor" href="#记忆预算" aria-label="Permalink to &quot;记忆预算&quot;">​</a></h3><ul><li>总记忆量预算；</li><li>单条长度预算；</li><li>注入上下文预算；</li><li>召回频率和衰减；</li><li>过期和归档。</li></ul><p>记忆预算与 Token Governor 联动，避免“记忆越多越智能”的假象。</p><h3 id="冲突、更新与置信度" tabindex="-1">冲突、更新与置信度 <a class="header-anchor" href="#冲突、更新与置信度" aria-label="Permalink to &quot;冲突、更新与置信度&quot;">​</a></h3><ul><li>新事实不能静默覆盖旧事实；</li><li>保留来源和时间；</li><li>冲突时标记或请求用户确认；</li><li>低置信度记忆不能单独触发高风险动作；</li><li>用户明确纠正优先；</li><li>过期事实可降权或遗忘。</li></ul><h3 id="遗忘" tabindex="-1">遗忘 <a class="header-anchor" href="#遗忘" aria-label="Permalink to &quot;遗忘&quot;">​</a></h3><p>遗忘必须传播到索引、缓存、设备副本和派生摘要。用户应能确认：</p><ul><li>忘了什么；</li><li>为什么忘；</li><li>哪些设备和索引已更新；</li><li>是否仍存在于备份；</li><li>如何验证。</li></ul><h3 id="记忆投毒与提示词注入" tabindex="-1">记忆投毒与提示词注入 <a class="header-anchor" href="#记忆投毒与提示词注入" aria-label="Permalink to &quot;记忆投毒与提示词注入&quot;">​</a></h3><p>网页、邮件、文档和外部工具输出都是不可信来源。它们可以成为候选记忆，但不能直接获得高可信度，更不能通过记忆扩大权限。高敏感或外部不可信内容应隔离、降权或拒绝写入。</p><h3 id="多设备同步与-ui" tabindex="-1">多设备同步与 UI <a class="header-anchor" href="#多设备同步与-ui" aria-label="Permalink to &quot;多设备同步与 UI&quot;">​</a></h3><ul><li>同步记忆必须携带版本、来源和 tombstone；</li><li>删除不能在另一台设备“复活”；</li><li>敏感记忆按设备范围过滤；</li><li>记忆浏览器显示“记住了什么、为什么召回、来自哪里”；</li><li>用户可纠正、删除、导出；</li><li>“为什么召回”不能只给模型解释，要有来源和规则证据。</li></ul><h3 id="记忆指标" tabindex="-1">记忆指标 <a class="header-anchor" href="#记忆指标" aria-label="Permalink to &quot;记忆指标&quot;">​</a></h3><ul><li>召回准确率；</li><li>错误记忆导致的返工；</li><li>用户纠正率；</li><li>遗忘合规率；</li><li>注入 Token 和延迟；</li><li>敏感信息泄漏尝试被阻断率。</li></ul>',29)])])}const p=e(r,[["render",o]]);export{m as __pageData,p as default};
